function verticalPage(page,d){const c=activeCategory;const v=verticals[c];const titles={customers:{barber:['Mijozlar kartotekasi','Mijozlar tarixi va aloqa ma’lumotlari'],dentist:['Bemorlar kartasi','Bemorlar ro‘yxati va tashriflari'],education:['O‘quvchilar bazasi','O‘quvchilar va ota-onalar bilan aloqa'],clinic:['Bemorlar reyestri','Bemorlar ro‘yxati'],retail:['Xaridorlar bazasi','Xaridorlar va aloqa ma’lumotlari'],restaurant:['Mijozlar bazasi','Mijozlar bilan aloqa'],auto_service:['Avtomobil egalari','Mijozlar va aloqa ma’lumotlari']},catalog:{barber:['Xizmatlar va narxlar','Sartaroshlik xizmatlari katalogi'],dentist:['Muolajalar katalogi','Stomatologik xizmatlar va narxlar'],education:['Kurslar katalogi','Ta’lim dasturlari va narxlar'],clinic:['Tibbiy xizmatlar','Klinika xizmatlari katalogi'],retail:['Mahsulotlar ombori','Mahsulotlar va narxlar'],restaurant:['Menyu boshqaruvi','Taomlar, ichimliklar va narxlar'],auto_service:['Servis xizmatlari','Xizmatlar va ehtiyot qismlar']},orders:{dentist:['Davolash rejalari','Bemorlar uchun davolash jarayonlari'],education:['O‘quv guruhlari','Guruhlar va o‘quv jarayonlari'],retail:['Savdolar','Sotuvlar va buyurtmalar'],restaurant:['Oshxona buyurtmalari','Yangi va bajarilayotgan buyurtmalar'],auto_service:['Ta’mirlash buyurtmalari','Avtomobil ta’mirlash jarayonlari']},appointments:{barber:['Navbatlar taqvimi','Ustalar va mijozlar qabuli'],dentist:['Shifokorlar qabuli','Bemorlar uchun qabul jadvali'],education:['Dars jadvali','Darslar va guruhlar jadvali'],clinic:['Qabul jadvali','Shifokorlar qabuli'],retail:['Yetkazib berishlar','Yetkazib berish vaqtlari'],restaurant:['Stollar bandligi','Stol bronlari va band vaqtlar'],auto_service:['Servisga yozilish','Avtomobillar uchun qabul vaqti']},team:{barber:['Ustalar jamoasi','Sartaroshlar va ish smenalari'],dentist:['Shifokorlar jamoasi','Shifokorlar va mutaxassislar'],education:['O‘qituvchilar','O‘qituvchilar tarkibi'],clinic:['Tibbiyot xodimlari','Shifokorlar va xodimlar'],retail:['Sotuvchilar','Do‘kon xodimlari'],restaurant:['Restoran xodimlari','Zal va oshxona xodimlari'],auto_service:['Ustalar','Mexaniklar va servis xodimlari']}};const info=titles[page]?.[c]||[names[page][0],names[page][2]];let body='';if(page==='customers')body=table(['ISM / F.I.SH.','TELEFON','RO‘YXATGA OLINGAN'],(d.customers||[]).map(x=>[esc(x.name),esc(x.phone||'—'),new Date(x.created_at).toLocaleDateString('uz-UZ')]));else if(page==='catalog')body=table(['NOMI','TURI','NARXI'],(d.catalog||[]).map(x=>[esc(x.name),x.kind==='service'?'Xizmat':'Mahsulot',money(x.price)]));else if(page==='orders')body=table(['NOMI','SUMMA','HOLAT'],(d.orders||[]).map(x=>[esc(x.title),money(x.amount),'<span class="status">'+esc(x.status)+'</span>']));else if(page==='appointments')body=table(['XIZMAT / TADBIR','SANA VA VAQT','HOLAT'],(d.appointments||[]).map(x=>[esc(x.service_name),new Date(x.starts_at).toLocaleString('uz-UZ'),'<span class="status good">'+esc(x.status)+'</span>']));else if(page==='team')body=empty('Jamoa bo‘limi','Xodimlarni qo‘shish va rollarni boshqarish bot orqali mavjud. Mini App xodimlar jadvali alohida ulanishi kerak.');else if(page==='payments')body=empty('To‘lovlar jurnali','To‘lovlarni qayd qilish bot orqali ishlaydi. Mini App to‘lovlar jadvali keyingi integratsiya bosqichida ulanadi.');else if(page==='reports')body='<div class="section-grid">'+stat('BUYURTMALAR',d.summary?.orders?.count||0,'▤','Bugungi yozuvlar')+stat('TUSHUM',money(d.summary?.payments?.total),'↗','Qayd etilgan to‘lovlar')+'</div>';return verticalHero(page)+'<section class="panel"><div class="panel-head"><div><div class="panel-title">'+info[0]+'</div><div class="panel-sub">'+info[1]+'</div></div><span class="tag">'+v.title.toUpperCase()+'</span></div>'+body+'</section>'}
